+            closeQuietly(zip);
+            throw e;
+        }
+        return new BoundedInputStream(zip, MAX_DECOMPRESSED_BYTES);
+    }
+
+    private static void closeQuietly(InputStream in) {
+        try {
+            in.close();
+        } catch (IOException ignored) {
+            // 닫기 실패는 수집 결과에 영향을 주지 않는다.
+        }
+    }
