+            return httpClient.send(request.build(), HttpResponse.BodyHandlers.ofInputStream());
+        } catch (HttpTimeoutException e) {
+            throw retryable(TIMEOUT);
+        } catch (IOException e) {
+            throw retryable(CONNECTION_FAILED);
+        } catch (InterruptedException e) {
+            Thread.currentThread().interrupt();
+            throw retryable(CONNECTION_FAILED);
+        }
+    }
+
+    private NewsHttpResponse toResponse(HttpResponse<InputStream> response, int status) {
+        if (status == 304) {
+            closeQuietly(response.body());
+            return new NewsHttpResponse(
+                    304,
+                    null,
+                    new byte[0],
+                    header(response, "etag"),
+                    header(response, "last-modified"));
+        }
+        if (status == 401 || status == 403) {
+            closeQuietly(response.body());
+            throw new NewsSourceClient.NewsSourceException(UNAUTHORIZED, false);
+        }
+        if (status == 429) {
+            closeQuietly(response.body());
+            throw retryable(RATE_LIMITED);
+        }
+        if (status >= 500) {
+            closeQuietly(response.body());
+            throw retryable(SERVER_ERROR);
+        }
+        if (status >= 400) {
+            closeQuietly(response.body());
+            throw new NewsSourceClient.NewsSourceException(CLIENT_ERROR, false);
+        }
