+        try {
+            uri = new URI(url.trim());
+        } catch (URISyntaxException e) {
+            throw reject(MALFORMED_URL);
+        }
+        if (!uri.isAbsolute()) {
+            throw reject(MALFORMED_URL);
+        }
+        return uri;
+    }
+
+    private static URI parseRelative(String location) {
+        if (location == null || location.isBlank()) {
+            throw reject(MALFORMED_URL);
+        }
+        try {
+            return new URI(location.trim());
+        } catch (URISyntaxException e) {
+            throw reject(MALFORMED_URL);
+        }
+    }
+}

