+
+    private static NewsSummaryPolicy.Input toInput(JsonNode node) {
+        Set<String> topics = new LinkedHashSet<>();
+        node.get("topics").forEach(topic -> topics.add(topic.asText()));
+        return new NewsSummaryPolicy.Input(
